package jp.tapmarker;
import java.util.*;
public final class PhaseEngine {
 public static final int CHANGE=0,MATCH=1,TIMEOUT=2,DISAPPEAR=3;
 public static final int CENTER=0,MARKERS=1,CURVE=2,BACK=3,STOP=4,WAIT=5,RETURN_APP=6;
 public static class Region {public String id,name;public float[] bounds;public boolean windowLocal;}
 public static class Watch {public String id,name="",regionId="",nextPhase="",historyRule="",historyPhase="";public int condition=CHANGE,action=CENTER,priority=10,waitMs=800;public long timeoutMs=5000,stableMs=0;public boolean fallback=false,pairedReference=false;public float threshold=.004f;public float[] reference,curve=new float[0];public long duration=500;public String[] markerIds=new String[0];
  public String[] guardIds=new String[0];public float[][] guardReferences=new float[0][];public float[] touchPoint=new float[0],markerPoints=new float[0];public boolean relativeCurve;
  // Runtime alternatives preserve the original single-screen evidence and its tolerance.
  public float[][] runtimePairedReferences;public float[] runtimeAlternative;public float runtimeAlternativeThreshold;public boolean runtimeBlocks,runtimeControlEvidence;
  public float distance(float[] sample){if(sample==null)return Float.POSITIVE_INFINITY;if(runtimeControlEvidence&&sample.length==1)return sample[0]==1?0:Float.POSITIVE_INFINITY;if(runtimeAlternative!=null&&sample.length==runtimeAlternative.length)return FlyCircuit.distance(runtimeAlternative,sample)*threshold/runtimeAlternativeThreshold;if(reference==null||reference.length!=sample.length)return Float.POSITIVE_INFINITY;if(pairedReference){float distance=blockDistance(reference,sample);if(runtimePairedReferences!=null)for(float[] variant:runtimePairedReferences)distance=Math.min(distance,blockDistance(variant,sample));return distance;}return runtimeBlocks?blockDistance(reference,sample):FlyCircuit.distance(reference,sample);}
 }
 static float blockDistance(float[] reference,float[] sample){if(reference.length!=sample.length||(reference.length!=768&&reference.length!=1536))return Float.POSITIVE_INFINITY;double worst=0;for(int anchor=0;anchor<reference.length/768;anchor++){double distance=0;for(int y=0;y<16;y+=2)for(int x=0;x<16;x+=2)for(int color=0;color<3;color++){double delta=0;for(int dy=0;dy<2;dy++)for(int dx=0;dx<2;dx++)delta+=reference[anchor*768+((y+dy)*16+x+dx)*3+color]-sample[anchor*768+((y+dy)*16+x+dx)*3+color];distance+=delta*delta/16;}worst=Math.max(worst,distance/192);}return (float)worst;}
 public static Watch copyWatch(Watch w){return copyWatch(w,new ReferencePool());}
 static Watch copyWatch(Watch w,ReferencePool pool){Watch a=new Watch();a.id=w.id;a.name=w.name;a.regionId=w.regionId;a.nextPhase=w.nextPhase;a.historyRule=w.historyRule;a.historyPhase=w.historyPhase;a.condition=w.condition;a.action=w.action;a.priority=w.priority;a.waitMs=w.waitMs;a.timeoutMs=w.timeoutMs;a.stableMs=w.stableMs;a.fallback=w.fallback;a.pairedReference=w.pairedReference;a.threshold=w.threshold;a.reference=pool.copy(w.reference);a.curve=w.curve.clone();a.duration=w.duration;a.markerIds=w.markerIds.clone();a.guardIds=w.guardIds.clone();a.guardReferences=new float[w.guardReferences.length][];for(int j=0;j<w.guardReferences.length;j++)a.guardReferences[j]=pool.copy(w.guardReferences[j]);a.touchPoint=w.touchPoint.clone();a.markerPoints=w.markerPoints.clone();a.relativeCurve=w.relativeCurve;return a;}
 public PhaseEngine runtimeCopy(){ReferencePool pool=new ReferencePool();PhaseEngine e=new PhaseEngine();e.initial=initial;e.current=current;e.strictRuntime=strictRuntime;e.windowRelative=windowRelative;e.recordingReviewRequired=recordingReviewRequired;for(Region r:regions.values()){Region c=new Region();c.id=r.id;c.name=r.name;c.bounds=r.bounds.clone();c.windowLocal=r.windowLocal;e.regions.put(c.id,c);}for(Phase p:phases.values()){Phase c=new Phase();c.id=p.id;c.name=p.name;c.graphX=p.graphX;c.graphY=p.graphY;c.markersDuring=p.markersDuring;c.learnedDuring=p.learnedDuring;c.terminal=p.terminal;for(Watch w:p.watches)c.watches.add(copyWatch(w,pool));e.phases.put(c.id,c);}return e;}
 public static class Phase {public String id,name;public float graphX=-1,graphY=-1;public boolean markersDuring=false,learnedDuring=false,terminal=false;public List<Watch> watches=new ArrayList<>();}
 public final Map<String,Region> regions=new LinkedHashMap<>();public final Map<String,Phase> phases=new LinkedHashMap<>();public String initial="",current="",lastCompletedRule="",sourcePhase="";public boolean strictRuntime=false,windowRelative=false,recordingReviewRequired=false;public String diagnostic="";final Map<String,Integer> confirmations=new HashMap<>();final Map<String,float[]> changes=new HashMap<>();final Map<String,Long> stableSince=new HashMap<>();long enteredAt;long epoch;final Map<String,ChangeTapDetector> detectors=new HashMap<>();final Set<String> latched=new HashSet<>();final List<Watch> pending=new ArrayList<>();
 public void enter(String id,long now){if(!phases.containsKey(id))throw new IllegalArgumentException("フェーズがありません");sourcePhase=current;current=id;enteredAt=now;epoch++;detectors.clear();latched.clear();pending.clear();confirmations.clear();changes.clear();stableSince.clear();diagnostic="";}
 public void clearTransitions(){for(Phase p:phases.values())p.watches.clear();clearHistory();}
 public void restartObservation(long now){String priorSource=sourcePhase;enter(current,now);sourcePhase=priorSource;}
 /** Discard stale evidence and callbacks without extending the current state deadline. */
 public void invalidateObservation(){restartObservation(enteredAt);}
 public void clearHistory(){lastCompletedRule="";sourcePhase="";pending.clear();detectors.clear();latched.clear();confirmations.clear();changes.clear();stableSince.clear();diagnostic="";}
 public boolean eligible(Watch w){return (w.historyRule.isEmpty()||w.historyRule.equals(lastCompletedRule))&&(w.historyPhase.isEmpty()||w.historyPhase.equals(sourcePhase));}
 public Watch rule(String id){for(Phase p:phases.values())for(Watch w:p.watches)if(id.equals(w.id))return w;return null;}
 public boolean terminal(){Phase p=phases.get(current);return p!=null&&p.terminal;}
 public List<Region> activeRegions(){LinkedHashMap<String,Region> selected=new LinkedHashMap<>();Phase p=phases.get(current);if(p!=null&&!p.terminal)for(Watch w:p.watches)if(eligible(w)){if((w.condition!=TIMEOUT||windowRelative&&w.action==CENTER)&&regions.containsKey(w.regionId))selected.put(w.regionId,regions.get(w.regionId));for(String guard:w.guardIds)if(regions.containsKey(guard))selected.put(guard,regions.get(guard));}return new ArrayList<>(selected.values());}
 public void observe(Map<String,float[]> samples,long now){Phase state=phases.get(current);if(state==null||state.terminal)return;if(strictRuntime){pending.clear();diagnostic="条件成立を待機";}for(Watch w:state.watches){if(!eligible(w)){detectors.remove(w.id);latched.remove(w.id);confirmations.remove(w.id);changes.remove(w.id);stableSince.remove(w.id);continue;}boolean fire=false;switch(w.condition){case TIMEOUT:if(now-enteredAt>=w.timeoutMs&&!latched.contains(w.id)){fire=true;if(!strictRuntime)latched.add(w.id);}break;case CHANGE:float[] changed=samples.get(w.regionId);if(changed==null)continue;ChangeTapDetector detector=detectors.get(w.id);if(detector==null){detector=new ChangeTapDetector();detectors.put(w.id,detector);}boolean pulse=detector.observe(changed,w.threshold);if(!strictRuntime){fire=pulse;break;}if(pulse){changes.put(w.id,changed.clone());confirmations.put(w.id,1);stableSince.put(w.id,now);}else if(changes.containsKey(w.id)){if(FlyCircuit.distance(changes.get(w.id),changed)<=w.threshold){int count=confirmations.getOrDefault(w.id,0)+1;confirmations.put(w.id,count);fire=count>=2&&now-stableSince.getOrDefault(w.id,now)>=w.stableMs&&!latched.contains(w.id);if(!fire)diagnostic="変化後の安定待ち："+Math.max(0,w.stableMs-(now-stableSince.getOrDefault(w.id,now)))+"ms";}else{changes.put(w.id,changed.clone());confirmations.put(w.id,1);stableSince.put(w.id,now);}}break;case DISAPPEAR:case MATCH:float[] sample=samples.get(w.regionId);if(w.reference==null){if(strictRuntime){Region region=regions.get(w.regionId);diagnostic="一致画像が未記録："+(region==null?w.regionId:region.name);}continue;}if(sample==null)continue;boolean matching=w.distance(sample)<=w.threshold;if(w.condition==DISAPPEAR)matching=!matching;matching=matching&&guardsMatch(w,samples);if(!matching){latched.remove(w.id);confirmations.remove(w.id);}else if(!latched.contains(w.id)){int count=confirmations.getOrDefault(w.id,0)+1;confirmations.put(w.id,count);fire=!strictRuntime||count>=2;if(fire&&!strictRuntime)latched.add(w.id);}break;default:continue;}if(fire&&(w.condition==CHANGE||w.condition==TIMEOUT)&&!guardsMatch(w,samples))fire=false;if(fire&&!pending.contains(w))pending.add(w);}}
 public boolean awaitingBranch(){if(!strictRuntime)return false;Phase p=phases.get(current);if(p==null)return false;for(Watch w:p.watches)if(eligible(w)&&((!w.nextPhase.isEmpty()&&!w.nextPhase.equals(current))||w.action==STOP)&&confirmations.getOrDefault(w.id,0)>0&&!latched.contains(w.id))return true;return false;}
 public Watch poll(){pending.removeIf(w->!eligible(w));if(pending.isEmpty())return null;if(strictRuntime){Phase state=phases.get(current);boolean specific=false;for(Watch w:state.watches)if(!w.fallback&&eligible(w)&&(pending.contains(w)||confirmations.getOrDefault(w.id,0)>0&&!latched.contains(w.id))){specific=true;break;}if(specific)pending.removeIf(w->w.fallback);else{boolean visual=false;for(Watch w:state.watches)if(w.fallback&&w.condition!=TIMEOUT&&eligible(w)&&(pending.contains(w)||confirmations.getOrDefault(w.id,0)>0&&!latched.contains(w.id))){visual=true;break;}if(visual)pending.removeIf(w->w.fallback&&w.condition==TIMEOUT);}if(pending.isEmpty())return null;ArrayList<Watch> exits=new ArrayList<>();for(Watch w:pending)if(!w.nextPhase.isEmpty()&&!w.nextPhase.equals(current)||w.action==STOP)exits.add(w);if(exits.isEmpty()&&awaitingBranch()){diagnostic="分岐候補を確認中 / メイン操作と連打を保留";pending.clear();return null;}List<Watch> candidates=exits.isEmpty()?pending:exits;boolean same=true;for(Watch candidate:candidates)if(!AutomatonGraph.sameEffect(this,state,candidates.get(0),candidate)){same=false;break;}if(!same){diagnostic="複数の分岐条件が成立 / 領域と見本画像を確認してください";pending.clear();return null;}Watch chosen=candidates.get(0);pending.clear();latched.add(chosen.id);diagnostic="条件確認済み："+(chosen.name.isEmpty()?chosen.id:chosen.name);return chosen;}Watch best=pending.get(0);for(Watch w:pending)if(w.priority<best.priority)best=w;pending.remove(best);return best;}
 public boolean guardsMatch(Watch w,Map<String,float[]> samples){if(w.guardIds.length!=w.guardReferences.length)return false;for(int i=0;i<w.guardIds.length;i++){float[] sample=samples.get(w.guardIds[i]);if(w.guardReferences[i]==null||w.guardReferences[i].length==0){diagnostic="補助領域の一致画像が未記録："+w.guardIds[i];return false;}if(sample==null||FlyCircuit.distance(w.guardReferences[i],sample)>w.threshold)return false;}return true;}
 public boolean confirmsAction(Watch w,String state,long expectedEpoch,Map<String,float[]> samples){Phase p=phases.get(current);if(!current.equals(state)||epoch!=expectedEpoch||p==null||!p.watches.contains(w)||!eligible(w))return false;if(w.condition!=MATCH)return guardsMatch(w,samples);float[] sample=samples.get(w.regionId);return w.reference!=null&&sample!=null&&w.distance(sample)<=w.threshold&&guardsMatch(w,samples);}
 public boolean finishIfCurrent(Watch w,String state,long expectedEpoch,long now){Phase p=phases.get(current);if(!current.equals(state)||epoch!=expectedEpoch||p==null||!p.watches.contains(w))return false;finish(w,now);return true;}
 public boolean cancelIfCurrent(Watch w,String state,long expectedEpoch){Phase p=phases.get(current);if(!current.equals(state)||epoch!=expectedEpoch||p==null||!p.watches.contains(w))return false;pending.remove(w);latched.remove(w.id);confirmations.remove(w.id);diagnostic="操作未完了・表示を再確認："+(w.name.isEmpty()?w.id:w.name);return true;}
 public void finish(Watch w,long now){lastCompletedRule=w.id;if(!w.nextPhase.isEmpty()&&(!strictRuntime||!w.nextPhase.equals(current))){enter(w.nextPhase,now);return;}if(strictRuntime){pending.clear();confirmations.remove(w.id);changes.remove(w.id);stableSince.remove(w.id);if(w.condition!=TIMEOUT&&w.condition!=DISAPPEAR)latched.remove(w.id);ChangeTapDetector detector=detectors.get(w.id);if(w.condition==CHANGE&&detector!=null)detector.reset();if(w.condition==TIMEOUT&&w.nextPhase.equals(current)){latched.remove(w.id);enteredAt=now;}return;}for(ChangeTapDetector d:detectors.values())d.reset();}
 public String validate(){return validate(true);}
 public String validateStart(){if(recordingReviewRequired)return "録画の操作確認が未完了です。かんたん編集で確認を完了してください";return validate(false);}
 private String validate(boolean requireReference){String relationError=AutomatonGraph.relationships(this);if(!relationError.isEmpty())return relationError;Phase p=phases.get(current);if(p==null)return "開始フェーズを選択してください";if(p.watches.isEmpty()&&!p.terminal)return "このフェーズにルールを追加してください";for(Phase phase:phases.values())for(Watch w:phase.watches){if(!w.historyRule.isEmpty()&&rule(w.historyRule)==null)return phase.name+"：履歴条件のルールがありません";if(!w.historyPhase.isEmpty()&&!phases.containsKey(w.historyPhase))return phase.name+"：履歴条件のフェーズがありません";if(w.condition!=TIMEOUT&&!regions.containsKey(w.regionId))return phase.name+"：監視領域がありません";if(w.action==CENTER&&!regions.containsKey(w.regionId))return phase.name+"：タップ領域がありません";if(requireReference&&(w.condition==MATCH||w.condition==DISAPPEAR)&&w.reference==null)return phase.name+"：一致する状態を記録してください";if(!w.nextPhase.isEmpty()&&!phases.containsKey(w.nextPhase))return phase.name+"：遷移先がありません";for(int i=0;i<w.guardIds.length;i++)if(!regions.containsKey(w.guardIds[i])||i>=w.guardReferences.length||(w.guardReferences[i]==null||requireReference&&w.guardReferences[i].length!=768))return phase.name+"：補助監視領域がありません";if(w.touchPoint.length!=0&&(w.touchPoint.length!=2||!ObservationLearner.validPoints(w.touchPoint)))return phase.name+"：学習タップ位置が無効です";if(w.relativeCurve&&!ObservationLearner.validPoints(w.curve))return phase.name+"：学習曲線が無効です";if(w.markerPoints.length!=0&&(w.markerPoints.length!=w.markerIds.length*2||!ObservationLearner.validPoints(w.markerPoints)))return phase.name+"：学習マーカー位置が無効です";if(w.action==MARKERS&&w.markerIds.length==0)return phase.name+"：マーカーを紐づけてください";if(w.action==CURVE&&w.curve.length<4)return phase.name+"：曲線を紐づけてください";}return "";}
}
